"use client";
import Link from "next/link";
import {useRouter} from "next/navigation";
import {useState,type FormEvent} from "react";
import {memberRequest,useMember} from "./member-provider";
export function AuthForm({register=false}:{register?:boolean}){
 const [busy,setBusy]=useState(false);const [error,setError]=useState("");const {setUser,user,loading}=useMember();const router=useRouter();
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(register&&data.password!==data.confirmPassword){setError("비밀번호 확인이 일치하지 않습니다.");return}setBusy(true);setError("");try{const result=await memberRequest(register?"register":"login",data);setUser(result.user);router.replace(register ? "/" : new URLSearchParams(window.location.search).get("next")==="checkout" ? "/checkout" : "/cart")}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 if(!loading&&user)return <section className="member-card member-narrow"><h1>이미 로그인되어 있습니다</h1><Link href="/account">내 정보 보기 →</Link></section>;
 return <section className="member-card member-narrow"><p className="member-eyebrow">COMPICK ACCOUNT</p><h1>{register?"회원가입":"로그인"}</h1><p>내 장바구니를 저장하고 다른 기기에서도 이어서 확인하세요.</p><form onSubmit={submit}><fieldset disabled={busy}><label>아이디<input name="loginId" autoComplete="username" required minLength={4} maxLength={30} pattern="[A-Za-z0-9_]{4,30}" placeholder="영문·숫자·밑줄 4~30자"/></label>{register&&<><label>이름<input name="name" autoComplete="name" required maxLength={50}/></label><label>이메일<input name="email" type="email" autoComplete="email" required maxLength={254}/></label></>}<label>비밀번호<input name="password" type="password" autoComplete={register?"new-password":"current-password"} required minLength={register?12:1} maxLength={72}/></label>{register&&<><small>12자 이상, UTF-8 기준 72바이트 이하로 입력하세요.</small><label>비밀번호 확인<input name="confirmPassword" type="password" autoComplete="new-password" required/></label></>}<button className="member-primary">{busy?"처리 중…":register?"가입하고 시작하기":"로그인"}</button></fieldset>{error&&<p role="alert" className="member-error">{error}</p>}</form><div className="member-form-footer"><Link href={register?"/login":"/register"}>{register?"이미 계정이 있나요? 로그인":"처음 오셨나요? 회원가입"}</Link><Link href="/">쇼핑몰로 돌아가기</Link></div></section>;
}
